uniform float speed : 0.0 .. 3.0 = 1.0;
uniform float scale : 0.5 .. 8.0 = 3.0;
uniform float intensity : 0.0 .. 1.0 = 0.7;
uniform vec3 water_color : color = 0.05, 0.3, 0.6;
uniform vec3 highlight_color : color = 0.8, 1.0, 1.0;
uniform float shimmer_speed : 0.0 .. 5.0 = 2.0;

state fixed phase1;
state fixed phase2;
state fixed phase3;
state fixed k1;
state fixed k2;
state fixed k3;
state fixed amp1;
state fixed amp2;
state fixed amp3;

void update() {
  phase1 = fract(phase1 + fixed(dt * speed * 0.15));
  phase2 = fract(phase2 + fixed(dt * speed * 0.23));
  phase3 = fract(phase3 + fixed(dt * speed * 0.37));
  phase3 = fract(phase3 + fixed(dt * shimmer_speed * 0.5));
  k1 = fixed(scale * 0.8);
  k2 = fixed(scale * 1.3);
  k3 = fixed(scale * 2.1);
  amp1 = fixed(intensity * 0.6);
  amp2 = fixed(intensity * 0.3);
  amp3 = fixed(intensity * 0.15);
}

vec3 shade(Led led) {
  fixed s = fixed(led.s);
  fixed ux = fixed(led.uv.x);
  fixed uy = fixed(led.uv.y);

  fixed n1 = sin(s * k1 + ux * k1 + phase1);
  fixed n2 = sin(s * k2 + uy * k2 + phase2);
  fixed n3 = sin(ux * k3 + uy * k3 + phase3);

  fixed caustic = n1 * amp1 + n2 * amp2 + n3 * amp3;
  caustic = caustic * fixed(0.5) + fixed(0.5);
  caustic = caustic * caustic;
  caustic = caustic * caustic;

  fixed v = caustic * fixed(2.0);
  v = clamp(v, fixed(0.0), fixed(1.0));

  fixed h = fixed(0.55);
  fixed s_sat = fixed(0.85);
  return hsv2rgb(h, s_sat, v);
}
